// Terminals.
func (q *UserQuery) Get() (*UserRow, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "one"
	if direct, used, err := orm.QueryDirect(ctx, ex, q.q.Req, acceptsUserDirect, scanUserDirect); used {
		if err != nil || len(direct) == 0 {
			return nil, err
		}
		return direct[0], nil
	}
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil || len(rows.Data) == 0 {
		return nil, err
	}
	return scanUser(rows.Data[0], rows.Assemble, rows), nil
}

func (q *UserQuery) Gets() (*orm.Collection[UserRow], error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	if direct, used, err := orm.QueryDirect(ctx, ex, q.q.Req, acceptsUserDirect, scanUserDirect); used {
		if err != nil {
			return nil, err
		}
		return collectUserDirect(direct, q.keyFn), nil
	}
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	return collectUser(rows, q.keyFn), nil
}

// Stream visits independently owned rows without accumulating the complete result.
// Returning false stops the query and closes its database cursor.
func (q *UserQuery) Stream(visit func(*UserRow) bool) (orm.StreamResult, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return orm.StreamResult{}, err
	}
	if visit == nil {
		return orm.StreamResult{}, &ir.Error{Code: orm.CodeIrInvalid, Msg: "stream visitor is required"}
	}
	q.q.Req.IR.Kind = "all"
	return orm.Stream(ctx, ex, q.q.Req, func(vals []any, rows *orm.Rows) bool {
		return visit(scanUser(vals, rows.Assemble, rows))
	})
}

// GetsBySeq applies seq = v and runs the collection terminal.
func (q *UserQuery) GetsBySeq(v int64) (*orm.Collection[UserRow], error) {
	return q.Seq(v).Gets()
}

// GetsByName applies name = v and runs the collection terminal.
func (q *UserQuery) GetsByName(v string) (*orm.Collection[UserRow], error) {
	return q.Name(v).Gets()
}

func collectUser(rows *orm.Rows, keyFn func(*UserRow) orm.Key) *orm.Collection[UserRow] {
	c := orm.NewCollection[UserRow](len(rows.Data))
	for _, vals := range rows.Data {
		r := scanUser(vals, rows.Assemble, rows)
		if keyFn != nil {
			c.Put(keyFn(r), r)
			continue
		}
		key, ok := orm.KeyFromRow(vals, rows.Assemble.Key)
		if !ok {
			panic("assembly collection key contains null")
		}
		c.Put(key, r)
	}
	return c
}

func collectUserDirect(rows []*UserRow, keyFn func(*UserRow) orm.Key) *orm.Collection[UserRow] {
	c := orm.NewCollection[UserRow](len(rows))
	for _, r := range rows {
		if keyFn != nil {
			c.Put(keyFn(r), r)
		} else {
			c.Put(orm.KeyFromValues([]any{r.Seq}), r)
		}
	}
	return c
}

